# Social Media Scraping: The Complete Guide for 2026
## Methods for Scraping Social Media
### Method 1: DIY Browser Automation
```javascript
const puppeteer = require('puppeteer');

async function scrapeProfile(url) {
  const browser = await puppeteer.launch();
  const page = await browser.newPage();

  await page.goto(url, { waitUntil: 'networkidle2' });

  // Extract data from page
  const data = await page.evaluate(() => {
    return {
      username: document.querySelector('header h2')?.innerText,
      bio: document.querySelector('header span')?.innerText,
      // ... more selectors
    };
  });

  await browser.close();
  return data;
}
```

### Method 3: Scraping APIs (Recommended)
```javascript
const response = await fetch(
  'https://api.sociavault.com/v1/scrape/instagram/profile?handle=nike',
  { headers: { 'x-api-key': API_KEY } }
);

const data = await response.json();
console.log(data.data.follower_count); // 300000000
```

## Platform-by-Platform Guide
### Instagram Scraping
```javascript
// Get Instagram profile
const profile = await fetch(
  `https://api.sociavault.com/v1/scrape/instagram/profile?handle=natgeo`,
  { headers: { 'x-api-key': API_KEY } }
);

const data = await profile.json();
console.log({
  followers: data.data.follower_count,      // 283,000,000
  posts: data.data.media_count,              // 28,947
  isVerified: data.data.is_verified          // true
});
```

```javascript
// Get Instagram posts
const posts = await fetch(
  `https://api.sociavault.com/v1/scrape/instagram/posts?handle=natgeo`,
  { headers: { 'x-api-key': API_KEY } }
);

const postsData = await posts.json();
postsData.data.forEach(post => {
  console.log({
    likes: post.like_count,
    comments: post.comment_count,
    caption: post.caption?.substring(0, 50)
  });
});
```

### TikTok Scraping
```javascript
// Get TikTok profile
const profile = await fetch(
  `https://api.sociavault.com/v1/scrape/tiktok/profile?handle=khaby.lame`,
